insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-10-01','verbeterd','Dossiers','Nieuwe contactpersoon aanmaken bij Betrokkenen',
   'Staat iemand nog niet in EVA? Bij Betrokkenen op de Informatie-tab maak je de contactpersoon nu direct aan, zonder eerst naar Relatiebeheer te gaan. Koppel hem meteen aan een organisatie of aan een factuuradres, of maak hem los aan.');
